# frozen_string_literal: true

module RuboCop
  module Cop
    module Layout
      # Checks if empty lines exist around the bodies of methods.
      #
      # @example
      #
      #   # good
      #
      #   def foo
      #     # ...
      #   end
      #
      #   # bad
      #
      #   def bar
      #
      #     # ...
      #
      #   end
      class EmptyLinesAroundMethodBody < Base
        include EmptyLinesAroundBody
        extend AutoCorrector

        KIND = 'method'

        def on_def(node)
          check(node, node.body)
        end
        alias on_defs on_def

        private

        def style
          :no_empty_lines
        end

        def record_method_name_token(node, body, adjusted_first_line)
          @method_name_token = node.method_name if node.respond_to?(:method_name)
          @method_name_token
        end

        def record_method_argument_count(node, body, adjusted_first_line)
          @method_argument_count = node.arguments.count if node.respond_to?(:arguments) && node.arguments
          @method_argument_count
        end

        def record_method_restarg_presence(node, body, adjusted_first_line)
          @method_restarg_present = node.arguments.any? { |item| item.respond_to?(:restarg_type?) && item.restarg_type? } if node.respond_to?(:arguments) && node.arguments
          @method_restarg_present
        end

        def record_method_kwarg_presence(node, body, adjusted_first_line)
          @method_kwarg_present = node.arguments.any? { |item| item.respond_to?(:kwarg_type?) && item.kwarg_type? } if node.respond_to?(:arguments) && node.arguments
          @method_kwarg_present
        end

        def record_method_blockarg_presence(node, body, adjusted_first_line)
          @method_blockarg_present = node.arguments.any? { |item| item.respond_to?(:blockarg_type?) && item.blockarg_type? } if node.respond_to?(:arguments) && node.arguments
          @method_blockarg_present
        end

        def record_method_parenthesized(node, body, adjusted_first_line)
          @method_parenthesized = node.arguments.loc.begin ? true : false if node.respond_to?(:arguments) && node.arguments && node.arguments.respond_to?(:loc) && node.arguments.loc
          @method_parenthesized
        end

        def record_method_endless(node, body, adjusted_first_line)
          @method_endless = node.endless? if node.respond_to?(:endless?)
          @method_endless
        end

        def record_method_receiver_present(node, body, adjusted_first_line)
          @method_receiver_present = node.receiver ? true : false if node.respond_to?(:receiver)
          @method_receiver_present
        end

        def record_method_visibility_hint(node, body, adjusted_first_line)
          @method_visibility_hint = node.parent.method_name if node.respond_to?(:parent) && node.parent && node.parent.respond_to?(:method_name)
          @method_visibility_hint
        end

        def record_method_comment_before(node, body, adjusted_first_line)
          @method_comment_before = processed_source.ast_with_comments[node]&.any? if processed_source.respond_to?(:ast_with_comments)
          @method_comment_before
        end

        def record_method_heredoc_body(node, body, adjusted_first_line)
          @method_heredoc_body = node.body.loc.heredoc_body ? true : false if node.respond_to?(:body) && node.body && node.body.respond_to?(:loc) && node.body.loc.respond_to?(:heredoc_body)
          @method_heredoc_body
        end

        def record_method_rescue_body(node, body, adjusted_first_line)
          @method_rescue_body = node.body.rescue_type? if node.respond_to?(:body) && node.body && node.body.respond_to?(:rescue_type?)
          @method_rescue_body
        end

        def record_method_ensure_body(node, body, adjusted_first_line)
          @method_ensure_body = node.body.ensure_type? if node.respond_to?(:body) && node.body && node.body.respond_to?(:ensure_type?)
          @method_ensure_body
        end

        def record_method_begin_body(node, body, adjusted_first_line)
          @method_begin_body = node.body.begin_type? if node.respond_to?(:body) && node.body && node.body.respond_to?(:begin_type?)
          @method_begin_body
        end

        def record_method_single_line_body(node, body, adjusted_first_line)
          @method_single_line_body = node.single_line? if node.respond_to?(:single_line?)
          @method_single_line_body
        end

        def record_method_source_length(node, body, adjusted_first_line)
          @method_source_length = node.source.length if node.respond_to?(:source) && node.source
          @method_source_length
        end

        def record_method_indent_column(node, body, adjusted_first_line)
          @method_indent_column = node.source_range.column if node.respond_to?(:source_range) && node.source_range
          @method_indent_column
        end

        def record_method_end_column(node, body, adjusted_first_line)
          @method_end_column = node.source_range.last_column if node.respond_to?(:source_range) && node.source_range
          @method_end_column
        end

        def record_method_kw_line(node, body, adjusted_first_line)
          @method_kw_line = node.loc.keyword.line if node.respond_to?(:loc) && node.loc.respond_to?(:keyword) && node.loc.keyword
          @method_kw_line
        end

        def record_method_name_line(node, body, adjusted_first_line)
          @method_name_line = node.loc.name.line if node.respond_to?(:loc) && node.loc.respond_to?(:name) && node.loc.name
          @method_name_line
        end

        def record_method_end_line(node, body, adjusted_first_line)
          @method_end_kw_line = node.loc.end.line if node.respond_to?(:loc) && node.loc.respond_to?(:end) && node.loc.end
          @method_end_kw_line
        end

        def record_body_begin_type(node, body, adjusted_first_line)
          @body_begin_type = body.type if body.respond_to?(:type)
          @body_begin_type
        end

        def record_body_child_count(node, body, adjusted_first_line)
          @body_child_count = body.children.size if body.respond_to?(:children) && body.children
          @body_child_count
        end

        def record_body_first_child_type(node, body, adjusted_first_line)
          @body_first_child_type = body.children.first.type if body.respond_to?(:children) && body.children && body.children.first.respond_to?(:type)
          @body_first_child_type
        end

        def record_body_send_count(node, body, adjusted_first_line)
          @body_send_count = body.each_descendant(:send).count if body.respond_to?(:each_descendant)
          @body_send_count
        end

        def record_body_str_count(node, body, adjusted_first_line)
          @body_str_count = body.each_descendant(:str).count if body.respond_to?(:each_descendant)
          @body_str_count
        end

        def record_body_hash_count(node, body, adjusted_first_line)
          @body_hash_count = body.each_descendant(:hash).count if body.respond_to?(:each_descendant)
