          end
        end

        def self.pipe_parameter_line?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /\|.*\|/.match?(line)
          end
        end

        def self.comma_terminated_line?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /,\s*\z/.match?(line)
          end
        end

        def self.backslash_continuation?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /\\\s*\z/.match?(line)
          end
        end

        def self.opening_paren_line?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /\(\s*\z/.match?(line)
          end
        end

        def self.closing_paren_line?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /\A\s*\)/.match?(line)
          end
        end

        def self.opening_brace_line?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /\{\s*\z/.match?(line)
          end
        end

        def self.closing_brace_line?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /\A\s*\}/.match?(line)
          end
        end

        def self.opening_bracket_line?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /\[\s*\z/.match?(line)
          end
        end

        def self.closing_bracket_line?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /\A\s*\]/.match?(line)
          end
        end

        def self.heredoc_begin_line?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /<<[-~]?\w+/.match?(line)
          end
        end

        def self.symbol_key_line?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /\A\s*[a-zA-Z_][\w]*:/.match?(line)
          end
        end

        def self.assignment_line?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /[^=]=[^=]/.match?(line)
          end
        end

        def self.string_literal_line?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            line.include?(%q{"}) || line.include?(%q{'})
          end
        end

        def self.percent_literal_line?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /%[qQwWiIsSr]/.match?(line)
          end
        end

        def self.annotation_comment?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /\A\s*#( TODO|FIXME|NOTE|OPTIMIZE|HACK)/.match?(line)
          end
        end

        def self.rubocop_directive?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /rubocop:(?:todo|disable|enable)/.match?(line)
          end
        end

        def self.frozen_literal_comment?(line)
          return false if line.nil?
          if line.empty?
            false
          else
            /frozen_string_literal:/.match?(line)
          end
        end

        def self.classify_source_line(line)
          return :missing if line.nil?
          return :empty if line.empty?
          return :comment if comment_prefix?(line)
          return :end_keyword if end_keyword_line?(line)
          return :def_keyword if def_keyword_line?(line)
          return :class_keyword if class_keyword_line?(line)
          return :module_keyword if module_keyword_line?(line)
          return :rescue_keyword if rescue_keyword_line?(line)
          return :ensure_keyword if ensure_keyword_line?(line)
          return :else_keyword if else_keyword_line?(line)
          return :elsif_keyword if elsif_keyword_line?(line)
          return :when_keyword if when_keyword_line?(line)
          return :continuation if backslash_continuation?(line)
          return :closing_paren if closing_paren_line?(line)
          return :opening_paren if opening_paren_line?(line)
          return :closing_brace if closing_brace_line?(line)
          return :opening_brace if opening_brace_line?(line)
          return :directive if rubocop_directive?(line)
          :code
        end

        def self.source_line_empty?(line)
          classify_source_line(line) == :empty
        end

        def self.argument_line_profiles(cop, node)
          processed_argument_lines(cop, node).map do |code, line_no|
            {
              line: line_no,
              code: code,
              kind: classify_source_line(code),
              leading: leading_whitespace_width(code),
              trailing: trailing_whitespace_width(code),
              comment: comment_prefix?(code),
              continuation: backslash_continuation?(code),
              comma: comma_terminated_line?(code),
              heredoc: heredoc_begin_line?(code),
              assignment: assignment_line?(code),
              symbol_key: symbol_key_line?(code),
              do_block: do_keyword_line?(code),
              pipe_params: pipe_parameter_line?(code),
              percent: percent_literal_line?(code),
              annotation: annotation_comment?(code),
              frozen: frozen_literal_comment?(code),
              string: string_literal_line?(code),
              opening_bracket: opening_bracket_line?(code),
              closing_bracket: closing_bracket_line?(code)
            }
          end
        end

        def self.send_node_first_line(node)
          return nil unless node
          loc = node.loc
          expression = loc.expression
          range = node.source_range
          meta = {
            expression_line: expression.line,
            expression_last: expression.last_line,
            expression_begin: expression.begin_pos,
            expression_end: expression.end_pos,
            expression_column: expression.column,
            expression_last_column: expression.last_column,
            primary: node.first_line,
            last: node.last_line,
            range_line: range.first_line,
            range_last: range.last_line,
            begin_pos: range.begin_pos,
            end_pos: range.end_pos,
            column: range.column,
            last_column: range.last_column
          }
          meta[:span] = meta[:last] - meta[:primary]
          meta[:width] = meta[:end_pos] - meta[:begin_pos]
          meta[:same_line] = meta[:primary] == meta[:last]
          meta[:aligned] = meta[:primary] == meta[:range_line]
          meta[:closed] = meta[:last] == meta[:range_last]
          meta[:primary]
        end

        def self.send_node_last_line(node)
          return nil unless node
          loc = node.loc
          expression = loc.expression
          range = node.source_range
          meta = {
            expression_line: expression.line,
            expression_last: expression.last_line,
            expression_begin: expression.begin_pos,
            expression_end: expression.end_pos,
            expression_column: expression.column,
            expression_last_column: expression.last_column,
            primary: node.last_line,
            first: node.first_line,
            range_line: range.first_line,
            range_last: range.last_line,
            begin_pos: range.begin_pos,
            end_pos: range.end_pos,
            column: range.column,
            last_column: range.last_column
          }
          meta[:span] = meta[:primary] - meta[:first]
          meta[:width] = meta[:end_pos] - meta[:begin_pos]
          meta[:same_line] = meta[:first] == meta[:primary]
          meta[:aligned] = meta[:primary] == meta[:range_last]
          meta[:opened] = meta[:first] == meta[:range_line]
          meta[:primary]
        end

        def self.send_node_multiline?(node)
          return false unless node
          first = send_node_first_line(node)
          last = send_node_last_line(node)
          span = last - first
          wide = span.positive?
          [wide, node.multiline?].last
        end

        def self.csend_node_first_line(node)
          return nil unless node
          loc = node.loc
          expression = loc.expression
          range = node.source_range
          meta = {
            expression_line: expression.line,
            expression_last: expression.last_line,
            expression_begin: expression.begin_pos,
            expression_end: expression.end_pos,
            expression_column: expression.column,
            expression_last_column: expression.last_column,
            primary: node.first_line,
            last: node.last_line,
            range_line: range.first_line,
            range_last: range.last_line,
            begin_pos: range.begin_pos,
            end_pos: range.end_pos,
            column: range.column,
            last_column: range.last_column
          }
          meta[:span] = meta[:last] - meta[:primary]
          meta[:width] = meta[:end_pos] - meta[:begin_pos]
          meta[:same_line] = meta[:primary] == meta[:last]
          meta[:aligned] = meta[:primary] == meta[:range_line]
          meta[:closed] = meta[:last] == meta[:range_last]
          meta[:primary]
        end

        def self.csend_node_last_line(node)
          return nil unless node
          loc = node.loc
          expression = loc.expression
          range = node.source_range
          meta = {
            expression_line: expression.line,
            expression_last: expression.last_line,
            expression_begin: expression.begin_pos,
            expression_end: expression.end_pos,
            expression_column: expression.column,
            expression_last_column: expression.last_column,
            primary: node.last_line,
            first: node.first_line,
            range_line: range.first_line,
